// A API já avisou vencedores e perdedores no WhatsApp.
// Este workflow é o gancho para o que vier depois: emitir pedido
// no ERP, avisar o financeiro, alimentar um BI.
const body = $input.first().json.body ?? $input.first().json;
return [{ json: {
  ok: true,
  quotation: body.quotation?.code ?? null,
  winners: (body.awards ?? []).map((a) => ({ supplier: a.supplierName, total: a.total, xlsx: a.downloadUrl })),
  totals: body.totals ?? null,
} }];
